-- =====================================================================================
-- CORRECCIÓN DE DATOS: Despachos 'Fallido-Saldo' representan un rechazo PREVIO a abrir
-- la electroválvula (no hay saldo suficiente). No se sirvió cerveza real ni se cobró
-- nada. Los datos originales tenían, por error, el volumen y precio del formato
-- solicitado en vez de cero.
-- =====================================================================================
UPDATE [dbo].[Despacho]
SET [mililitros_servidos] = 0,
    [precio_cobrado] = 0.00
WHERE [estado] = N'Fallido-Saldo'
GO
-- =====================================================================================
-- CASOS DE EJEMPLO: fallos que ocurren DURANTE el servido (la cerveza ya salió
-- físicamente de la canilla; un ROLLBACK de la base de datos no la devuelve al barril).
-- Se registra el volumen efectivamente servido y una compensación al cliente.
-- =====================================================================================
INSERT [dbo].[Despacho] ([id_tarjeta], [id_canilla], [id_barril], [id_formato], [mililitros_servidos], [precio_cobrado], [monto_compensacion], [fecha_hora], [estado]) VALUES (N'A1B2C3D4E5', 2, 2, 2, 180, CAST(0.00 AS Decimal(10, 2)), CAST(500.00 AS Decimal(10, 2)), CAST(N'2026-09-10T19:22:10.000' AS DateTime), N'Fallido-Hardware')
