-- Coherencia temporal: la fecha de desconexión, si existe, no puede ser anterior a la conexión
ALTER TABLE [dbo].[Barril]  WITH CHECK ADD CONSTRAINT [CK_Barril_Fechas] CHECK  (([fecha_desconexion] IS NULL OR [fecha_desconexion]>=[fecha_conexion]))
GO
ALTER TABLE [dbo].[Barril] CHECK CONSTRAINT [CK_Barril_Fechas]
GO
-- Coherencia estado <-> conexión: un barril 'Conectado' siempre tiene canilla asignada y
-- no tiene fecha de desconexión; un barril 'Agotado' o 'Retirado' siempre tiene fecha de baja
ALTER TABLE [dbo].[Barril]  WITH CHECK ADD CONSTRAINT [CK_Barril_Estado_Conexion] CHECK  (
    ([estado]='Conectado' AND [id_canilla] IS NOT NULL AND [fecha_desconexion] IS NULL)
    OR
    ([estado] IN ('Agotado','Retirado') AND [fecha_desconexion] IS NOT NULL)
)
GO
ALTER TABLE [dbo].[Barril] CHECK CONSTRAINT [CK_Barril_Estado_Conexion]
GO
-- Regla crítica de unicidad activa: una canilla solo puede tener UN barril 'Conectado' a la vez
CREATE UNIQUE NONCLUSTERED INDEX [UQ_Barril_Canilla_Conectado]
ON [dbo].[Barril]([id_canilla])
WHERE ([estado]='Conectado' AND [fecha_desconexion] IS NULL)
