GO
ALTER TABLE [dbo].[Despacho] CHECK CONSTRAINT [CK_Despacho_Estado]
GO
-- Antes: mililitros_servidos > 0, impedía registrar un rechazo previo a abrir la válvula.
-- Ahora: >= 0, para permitir 'Fallido-Saldo' (0 ml servidos).
ALTER TABLE [dbo].[Despacho]  WITH CHECK ADD CONSTRAINT [CK_Despacho_MlServidos] CHECK  (([mililitros_servidos]>=(0)))
GO
ALTER TABLE [dbo].[Despacho] CHECK CONSTRAINT [CK_Despacho_MlServidos]
GO
ALTER TABLE [dbo].[Despacho]  WITH CHECK ADD CONSTRAINT [CK_Despacho_Montos] CHECK  (([precio_cobrado]>=(0) AND [monto_compensacion]>=(0)))
GO
ALTER TABLE [dbo].[Despacho] CHECK CONSTRAINT [CK_Despacho_Montos]
GO
-- Regla de integridad de negocio: coherencia entre estado, volumen servido, cobro y compensación
ALTER TABLE [dbo].[Despacho]  WITH CHECK ADD CONSTRAINT [CK_Despacho_Coherencia_Estado] CHECK  (
    ([estado]='Exitoso' AND [mililitros_servidos]>(0) AND [precio_cobrado]>(0) AND [monto_compensacion]=(0))
    OR
    ([estado]='Fallido-Saldo' AND [mililitros_servidos]=(0) AND [precio_cobrado]=(0) AND [monto_compensacion]=(0))
    OR
    ([estado] IN ('Fallido-Hardware','Fallido-Stock') AND [mililitros_servidos]>=(0) AND [monto_compensacion]>=(0))
)
GO
ALTER TABLE [dbo].[Despacho] CHECK CONSTRAINT [CK_Despacho_Coherencia_Estado]
GO
