ALTER TABLE [dbo].[PrecioCerveza] CHECK CONSTRAINT [CK_PrecioCerveza_Vigencia]
GO
-- Evita duplicar el inicio de vigencia de un mismo precio para la misma cerveza+formato
ALTER TABLE [dbo].[PrecioCerveza]  ADD CONSTRAINT [UQ_PrecioCerveza_Inicio] UNIQUE ([id_cerveza], [id_formato], [vigente_desde])
GO
-- Regla crítica de unicidad activa: solo puede existir UN precio vigente actual
-- (vigente_hasta IS NULL) por cada combinación cerveza+formato
CREATE UNIQUE NONCLUSTERED INDEX [UQ_PrecioCerveza_VigenteActual]
ON [dbo].[PrecioCerveza]([id_cerveza], [id_formato])
WHERE ([vigente_hasta] IS NULL)
